const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function reportRows(job){
  if(job.status!=='completed'||!job.result)throw new Error('A completed analysis is required.');
  const r=job.result;
  return [['Case',job.case_id],['Slide',job.filename],['Classification',r.classification],['Ensemble score',r.score],['Decision threshold',r.threshold],['Tissue patches',r.patchCount],['Model version',r.modelVersion],['Input SHA-256',r.inputSha256??'Not recorded'],['Submitted',job.created_at],['Completed',job.updated_at],...Object.entries(r.expertScores??{})];
}
export function reportHtml(job,images=[]){
  const rows=reportRows(job);
  const figures=images.filter(im=>['heatmap','thumbnail'].includes(im.kind)&&/^data:image\/(png|jpeg);base64,[A-Za-z0-9+/=]+$/.test(im.data)).map(im=>`<figure><img src="${im.data}" alt="${im.kind==='heatmap'?'ResNet50 patch-score heatmap':'Tissue thumbnail'}"><figcaption>${im.kind==='heatmap'?'ResNet50 patch-score heatmap; not a tumor boundary or combined ensemble map.':'Tissue thumbnail'}</figcaption></figure>`).join('');
  return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width"><title>STEGASUS analysis report</title><style>body{font:16px Georgia,serif;max-width:900px;margin:40px auto;padding:0 24px;color:#241c33}h1{color:#6034a4}table{border-collapse:collapse;width:100%}th,td{text-align:left;padding:10px;border-bottom:1px solid #ddd;overflow-wrap:anywhere}img{max-width:100%}figure{margin:24px 0}figcaption{font-size:14px}button{padding:10px}@media print{button{display:none}figure{break-inside:avoid}}</style><button onclick="window.print()">Print / Save as PDF</button><h1>STEGASUS analysis report</h1><p>Completed slide analysis for ${escape(job.case_id)}.</p><table>${rows.map(([k,v])=>`<tr><th>${escape(k)}</th><td>${escape(v)}</td></tr>`).join('')}</table><h2>Interpretation</h2><p>The ensemble score is compared with the recorded decision threshold. Below threshold does not rule out metastasis. These are investigational research outputs and require human review.</p>${figures||'<p>Images are available separately in the Studio. This report contains no embedded images.</p>'}<p>The heatmap displays ResNet50 patch scores, not graph attention, an ensemble heatmap, or verified lesion boundaries. Single-slide results do not establish cohort accuracy or clinical diagnostic performance.</p></html>`;
}
